use abcurves_native::*;
use std::{env,fs::File,io::{BufWriter,Write},time::Instant};
fn main(){let a:Vec<_>=env::args().collect();let m=Model::load(&a[1]).unwrap();let mut p=Planner::new(&m,Default::default()).unwrap();let c=m.info().unwrap().commitment_ms;let mut ctl=SegmentController::new(&mut p,Default::default()).unwrap();let mut rows=Vec::with_capacity(8000);let mut samples=[Sample::default();32];
 for i in 0..2528{let t=i as i64*c as i64*1000;let target=Vec2{x:420.+200.*(i as f64*0.09).sin(),y:170.+90.*(i as f64*0.071).cos()};let start=Instant::now();ctl.absolute(target,t,t).unwrap();rows.push(("observation",start.elapsed().as_secs_f64()*1e6,0,0));let start=Instant::now();let (_,meta)=ctl.next_segment_into(&mut samples).unwrap();rows.push(("segment",start.elapsed().as_secs_f64()*1e6,meta.fresh_planning_decision,meta.motor_inference));let start=Instant::now();let _meta=ctl.metadata().unwrap();rows.push(("metadata",start.elapsed().as_secs_f64()*1e6,0,0));if i==127{rows.clear();}}
 let mut out=BufWriter::new(File::create(format!("{}.csv",a[2])).unwrap());writeln!(out,"stage,us,fresh,active").unwrap();for (stage,us,fresh,active)in rows{writeln!(out,"{stage},{us:.9},{fresh},{active}").unwrap();}}
